import json, traceback
from pathlib import Path
import adsk.core, adsk.fusion
WORK=Path(r'C:\Users\kikom\Documents\GitHub\GreenTitan')
namespace={'__name__':'greentitan_roof_reset_cleanup'}
exec((WORK/'cad/roof_reset/fusion_present_concept.py').read_text(encoding='utf-8'),namespace)
result={'phase':'preflight','closed':False,'cloud_designs_deleted':False,'marker':'GreenTitanCompactCowl','run_id':EXPECTED['run_id']}
try:
    app=adsk.core.Application.get()
    baseline=json.loads(namespace['SOURCE_RECORD'].read_text(encoding='utf-8'))
    original=namespace['_source_guard'](app,baseline)
    matches=[]
    for document in app.documents:
        if not document.products.itemByProductType('DesignProductType'):continue
        design=namespace['_design'](document)
        marker=design.rootComponent.attributes.itemByName('GreenTitanCompactCowl','run_id')
        if marker and marker.value==EXPECTED['run_id']:matches.append(document)
    if not matches:
        result['phase']='rejected_cowl_not_open'
    else:
        if len(matches)!=1:raise RuntimeError('Ambiguous rejected cowl documents; leave intact.')
        document=matches[0]
        if document==original or document.isSaved:raise RuntimeError('Refusing to close original or saved document.')
        design=namespace['_design'](document)
        fingerprint=namespace['_fingerprint'];near=namespace['_near']
        if not near(fingerprint(design,EXPECTED['reference_prefix']),EXPECTED['reference_fingerprint']):
            raise RuntimeError('Rejected cowl reference changed; leave intact.')
        for part in EXPECTED['parts']:
            if not near(fingerprint(design,part['prefix'],accurate=True),part['imported_geometry']):
                raise RuntimeError('Rejected cowl part changed; leave intact: '+part['name'])
        if namespace['_reserve_state'](design,EXPECTED['reference_prefix'])!=EXPECTED['reserve_state']:
            raise RuntimeError('Rejected cowl reserve visibility changed; leave intact.')
        result['document_name']=document.name
        if not document.close(False):raise RuntimeError('Could not close the marker-verified rejected cowl.')
        result.update({'phase':'rejected_cowl_closed','closed':True,'fingerprints_verified':True})
    namespace['_source_guard'](app,baseline)
    original.activate()
    result.update({'source_v3_modified':False,'source_geometry_unchanged':True,'active_document':original.name})
except Exception:
    result['phase']='error';result['error']=traceback.format_exc()
finally:
    (WORK/'outputs/chassis_reference/fusion_rejected_cowl_close_result.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
